const STORIES=[{"u": 2, "t": "小明生病了", "tv": "Tiểu Minh bị ốm", "s": [["小明很喜欢运动，他最喜欢踢足球。", "Tiểu Minh rất thích thể thao, cậu thích đá bóng nhất."], ["他每天早上六点起床，和他的小狗一起去跑步。", "Mỗi sáng cậu dậy lúc sáu giờ, cùng chú chó nhỏ của mình đi chạy bộ."], ["星期一早上，小明没有起床。", "Sáng thứ Hai, Tiểu Minh không dậy."], ["妈妈问他：“你怎么了？”", "Mẹ hỏi cậu: “Con sao thế?”"], ["小明说：“妈妈，我生病了。”", "Tiểu Minh nói: “Mẹ ơi, con bị ốm rồi.”"], ["医生来了，给他吃了药。", "Bác sĩ đến, cho cậu uống thuốc."], ["医生说：“你要在家休息三天，不能去学校。”", "Bác sĩ nói: “Cháu phải nghỉ ở nhà ba ngày, không được đến trường.”"], ["小明想：“三天不能踢足球，我不高兴！”", "Tiểu Minh nghĩ: “Ba ngày không được đá bóng, mình chẳng vui chút nào!”"], ["这三天，小狗每天都在小明的床前面，不睡觉，也不出去。", "Ba ngày ấy, ngày nào chú chó cũng nằm trước giường Tiểu Minh, không ngủ, cũng chẳng ra ngoài."], ["星期四早上，小明的身体好了。", "Sáng thứ Năm, Tiểu Minh đã khỏe lại."], ["他六点起床，要和小狗一起去跑步。", "Cậu dậy lúc sáu giờ, định cùng chú chó đi chạy bộ."], ["小狗看了看他，没有起来。", "Chú chó nhìn cậu một cái rồi không chịu dậy."], ["妈妈说：“这三天它也很忙，现在它要休息了！”", "Mẹ nói: “Ba ngày nay nó cũng bận lắm, giờ đến lượt nó nghỉ ngơi rồi!”"]], "q": [{"q": "Tiểu Minh thích môn thể thao nào nhất?", "o": ["Chạy bộ", "Đá bóng", "Bơi lội", "Bóng rổ"], "a": 1}, {"q": "Bác sĩ bảo Tiểu Minh nghỉ ở nhà mấy ngày?", "o": ["Một ngày", "Hai ngày", "Bốn ngày", "Ba ngày"], "a": 3}, {"q": "Sáng thứ Năm, chú chó làm gì?", "o": ["Không chịu dậy", "Chạy ra ngoài trước", "Bị ốm", "Đi tìm bác sĩ"], "a": 0}]}, {"u": 4, "t": "粉色的手表", "tv": "Chiếc đồng hồ màu hồng", "s": [["今天是王方的生日。", "Hôm nay là sinh nhật Vương Phương."], ["早上，她的丈夫张东在看报纸、喝牛奶，什么也没说。", "Buổi sáng, chồng cô là Trương Đông ngồi đọc báo, uống sữa, chẳng nói gì cả."], ["王方想：“他不知道今天是我的生日吗？”", "Vương Phương nghĩ: “Anh ấy không biết hôm nay là sinh nhật mình sao?”"], ["下午，王方很忙，没有时间想这个。", "Buổi chiều Vương Phương rất bận, không có thời gian nghĩ đến chuyện đó."], ["晚上，张东开车来学校接她。", "Buổi tối, Trương Đông lái xe đến trường đón cô."], ["他们回家了，房间里有很多人！", "Họ về nhà, trong phòng có rất nhiều người!"], ["大卫、玛丽和李月都在，他们说：“生日快乐！”", "David, Mary và Lý Nguyệt đều ở đó, họ nói: “Chúc mừng sinh nhật!”"], ["张东送给王方一个手表。", "Trương Đông tặng Vương Phương một chiếc đồng hồ."], ["手表是粉色的，王方非常喜欢这个颜色。", "Đồng hồ màu hồng, Vương Phương rất thích màu này."], ["王方问：“这个手表是在哪儿买的？”", "Vương Phương hỏi: “Đồng hồ này anh mua ở đâu thế?”"], ["张东说：“是在学校旁边的商店买的。”", "Trương Đông nói: “Anh mua ở cửa hàng bên cạnh trường.”"], ["玛丽说：“这两个星期，张东每天都问我们：王方最喜欢什么颜色？”", "Mary nói: “Hai tuần nay, ngày nào Trương Đông cũng hỏi bọn mình: Vương Phương thích màu gì nhất?”"], ["王方看了看张东，说：“你真好！”", "Vương Phương nhìn Trương Đông và nói: “Anh thật tốt!”"]], "q": [{"q": "Buổi sáng Trương Đông làm gì?", "o": ["Chuẩn bị quà", "Lái xe đi làm", "Đọc báo và uống sữa", "Gọi điện cho bạn"], "a": 2}, {"q": "Chiếc đồng hồ màu gì?", "o": ["Màu hồng", "Màu đỏ", "Màu trắng", "Màu đen"], "a": 0}, {"q": "Trương Đông mua đồng hồ ở đâu?", "o": ["Ở Bắc Kinh", "Trên mạng", "Ở bệnh viện", "Ở cửa hàng cạnh trường"], "a": 3}]}, {"u": 6, "t": "大卫要运动", "tv": "David phải vận động", "s": [["大卫很喜欢吃东西，他最喜欢吃羊肉面条。", "David rất thích ăn, món anh thích nhất là mì thịt cừu."], ["他今年八十公斤，医生说他要多运动。", "Năm nay anh nặng tám mươi cân, bác sĩ bảo anh phải vận động nhiều hơn."], ["大卫说：“好吧，以后我天天运动！”", "David nói: “Được thôi, từ nay ngày nào tôi cũng vận động!”"], ["星期一他去游泳，星期二他去打篮球，星期三他还去游泳。", "Thứ Hai anh đi bơi, thứ Ba anh đi chơi bóng rổ, thứ Tư anh lại đi bơi."], ["他觉得运动以后身体还不错。", "Anh thấy sau khi vận động, người cũng khá khỏe."], ["一个星期以后，他去医院看医生。", "Một tuần sau, anh đến bệnh viện gặp bác sĩ."], ["医生问：“你现在多少公斤？”", "Bác sĩ hỏi: “Bây giờ anh nặng bao nhiêu cân?”"], ["大卫说：“八十一公斤。”", "David nói: “Tám mươi mốt cân.”"], ["医生问：“你天天运动，怎么还多了一公斤？”", "Bác sĩ hỏi: “Ngày nào anh cũng vận động, sao lại tăng thêm một cân?”"], ["大卫的姐姐在旁边说：“因为运动以后他就想吃东西，所以每天都吃很多羊肉面条！”", "Chị gái David đứng bên cạnh nói: “Vì tập xong là nó lại thèm ăn, nên ngày nào cũng ăn thật nhiều mì thịt cừu!”"], ["医生说：“以后运动可以，羊肉面条不可以！”", "Bác sĩ nói: “Từ nay vận động thì được, mì thịt cừu thì không!”"], ["大卫想了想，问：“那……我可以吃鱼吗？”", "David nghĩ một lúc rồi hỏi: “Vậy… tôi ăn cá được không ạ?”"]], "q": [{"q": "Món David thích ăn nhất là gì?", "o": ["Cá", "Cơm", "Mì thịt cừu", "Hoa quả"], "a": 2}, {"q": "Sau một tuần, David nặng bao nhiêu cân?", "o": ["79 cân", "80 cân", "82 cân", "81 cân"], "a": 3}, {"q": "Vì sao David tăng cân?", "o": ["Tập xong anh ăn rất nhiều mì thịt cừu", "Anh không đi bơi", "Anh ngủ quá nhiều", "Anh uống nhiều cà phê"], "a": 0}]}, {"u": 8, "t": "去机场接朋友", "tv": "Ra sân bay đón bạn", "s": [["张东的公司离机场很远。", "Công ty của Trương Đông cách sân bay rất xa."], ["今天他要去机场接一个美国朋友，他叫大卫。", "Hôm nay anh phải ra sân bay đón một người bạn Mỹ tên là David."], ["他们还没有见过面。", "Họ chưa từng gặp mặt nhau."], ["大卫在电话里告诉他：“我很高，衣服是白的。”", "David nói với anh qua điện thoại: “Tôi rất cao, mặc áo trắng.”"], ["张东坐公共汽车去机场，路上车太多了，公共汽车非常慢。", "Trương Đông đi xe buýt ra sân bay, trên đường xe cộ quá đông, xe buýt đi rất chậm."], ["他坐了两个小时，到机场的时候已经三点了。", "Anh ngồi xe mất hai tiếng, lúc đến sân bay đã ba giờ."], ["机场里人很多，他找了很长时间。", "Sân bay rất đông người, anh tìm rất lâu."], ["他看见一个很高的人，衣服是白的。", "Anh nhìn thấy một người rất cao, mặc áo trắng."], ["张东问：“你好，你是大卫吗？”", "Trương Đông hỏi: “Xin chào, anh là David phải không?”"], ["那个人说：“对不起，我不是大卫，我是这儿的服务员。”", "Người đó nói: “Xin lỗi, tôi không phải David, tôi là nhân viên phục vụ ở đây.”"], ["张东让服务员帮他找一下。", "Trương Đông nhờ người phục vụ tìm giúp."], ["服务员想了想，说：“你的朋友是不是在那个咖啡店里？”", "Người phục vụ nghĩ một lát rồi nói: “Có phải bạn anh ở trong quán cà phê kia không?”"], ["大卫坐在咖啡店里，他说：“我等了你两个小时，已经喝了三杯咖啡了。这儿的咖啡真贵！”", "David đang ngồi trong quán cà phê, anh nói: “Tôi đợi anh hai tiếng rồi, đã uống ba cốc cà phê. Cà phê ở đây đắt thật!”"]], "q": [{"q": "David dặn Trương Đông nhận ra mình bằng cách nào?", "o": ["Người thấp, áo đen", "Người cao, áo trắng", "Cầm một cốc cà phê", "Đứng cạnh cửa ra"], "a": 1}, {"q": "Người cao mặc áo trắng mà Trương Đông gặp đầu tiên là ai?", "o": ["Một người bạn Mỹ", "Một tài xế", "Nhân viên phục vụ ở sân bay", "Một bác sĩ"], "a": 2}, {"q": "Khi được tìm thấy, David đã uống mấy cốc cà phê?", "o": ["Ba cốc", "Một cốc", "Hai cốc", "Bốn cốc"], "a": 0}]}, {"u": 10, "t": "谁帮我做题？", "tv": "Ai giúp con làm bài?", "s": [["星期六上午，小明正在家里做汉语题。", "Sáng thứ Bảy, Tiểu Minh đang ở nhà làm bài tập tiếng Trung."], ["第一个题他做完了，第二个题他看不懂。", "Câu thứ nhất cậu đã làm xong, câu thứ hai thì cậu đọc không hiểu."], ["他去问哥哥，哥哥正在看手机，说：“别问我，我很忙。”", "Cậu đi hỏi anh trai, anh đang xem điện thoại, nói: “Đừng hỏi anh, anh bận lắm.”"], ["他去问爸爸，爸爸正在洗车，说：“问你妈妈吧。”", "Cậu đi hỏi bố, bố đang rửa xe, nói: “Hỏi mẹ con đi.”"], ["妈妈正在做鸡蛋面条，她也没有时间。", "Mẹ đang nấu mì trứng, mẹ cũng không có thời gian."], ["小明很不高兴，他说：“你们都不帮助我！”", "Tiểu Minh rất không vui, cậu nói: “Mọi người chẳng ai giúp con cả!”"], ["妈妈想了想，说：“谁帮小明做完题，谁就可以先吃西瓜。”", "Mẹ nghĩ một lát rồi nói: “Ai giúp Tiểu Minh làm xong bài thì người đó được ăn dưa hấu trước.”"], ["哥哥不看手机了，爸爸也不洗车了。", "Anh trai thôi xem điện thoại, bố cũng thôi rửa xe."], ["大家都来帮助小明，十分钟就做完了。", "Cả nhà đều đến giúp Tiểu Minh, mười phút là làm xong."], ["星期一，王老师说：“小明，十个题你做错了九个，第一个是对的。”", "Thứ Hai, cô Vương nói: “Tiểu Minh, mười câu em làm sai chín câu, chỉ câu thứ nhất là đúng.”"], ["小明说：“老师，第一个题是我做的，后面的都是我家人做的。”", "Tiểu Minh nói: “Thưa cô, câu thứ nhất là em làm, mấy câu sau đều do người nhà em làm ạ.”"]], "q": [{"q": "Khi Tiểu Minh đến hỏi, anh trai đang làm gì?", "o": ["Rửa xe", "Nấu mì", "Ăn dưa hấu", "Xem điện thoại"], "a": 3}, {"q": "Mẹ hứa điều gì với người giúp Tiểu Minh?", "o": ["Được ăn dưa hấu trước", "Được đi xem phim", "Được mua điện thoại mới", "Được ăn mì trứng"], "a": 0}, {"q": "Câu nào trong bài là do Tiểu Minh tự làm?", "o": ["Câu thứ hai", "Cả mười câu", "Câu thứ nhất", "Không câu nào"], "a": 2}]}, {"u": 12, "t": "弟弟看雪", "tv": "Em trai ngắm tuyết", "s": [["小明家住在北京，他有一个弟弟，今年五岁。", "Nhà Tiểu Minh ở Bắc Kinh, cậu có một em trai năm nay năm tuổi."], ["去年下雪的时候，弟弟生病了，没有看见雪。", "Năm ngoái lúc tuyết rơi, em trai bị ốm nên không được thấy tuyết."], ["今天早上，外面下雪了。", "Sáng nay, bên ngoài có tuyết rơi."], ["弟弟非常高兴，他说：“我要出去看雪！”", "Em trai vô cùng vui sướng, nói: “Em muốn ra ngoài ngắm tuyết!”"], ["妈妈说：“今天零下十度，比昨天冷多了，你要多穿一点儿衣服。”", "Mẹ nói: “Hôm nay âm mười độ, lạnh hơn hôm qua nhiều, con phải mặc thêm áo vào.”"], ["弟弟穿了一件、两件、三件……一共穿了六件衣服。", "Em trai mặc một cái, hai cái, ba cái… mặc tất cả sáu cái áo."], ["他穿得太多了，走得非常慢。", "Em mặc nhiều quá nên đi rất chậm."], ["外面有很多孩子，男孩子、女孩子都在雪里跑来跑去。", "Bên ngoài có rất nhiều trẻ con, cả bé trai lẫn bé gái đều chạy tới chạy lui trong tuyết."], ["弟弟也想跑，可是他跑了几米，就坐在雪里了。", "Em trai cũng muốn chạy, nhưng mới chạy được vài mét đã ngồi phịch xuống tuyết."], ["他起不来了。", "Em không đứng dậy nổi nữa."], ["小明从家里出来，看见弟弟坐在雪里。", "Tiểu Minh từ trong nhà đi ra, thấy em trai đang ngồi trong tuyết."], ["小明问：“你冷不冷？”", "Tiểu Minh hỏi: “Em có lạnh không?”"], ["弟弟说：“不冷，我太热了！我要回家，少穿四件！”", "Em trai nói: “Không lạnh, em nóng quá! Em muốn về nhà cởi bớt bốn cái áo!”"]], "q": [{"q": "Hôm nay nhiệt độ là bao nhiêu?", "o": ["Không độ", "Âm năm độ", "Âm mười độ", "Mười độ"], "a": 2}, {"q": "Em trai đã mặc tất cả bao nhiêu cái áo?", "o": ["Sáu cái", "Bốn cái", "Ba cái", "Hai cái"], "a": 0}, {"q": "Vì sao cuối cùng em trai muốn về nhà?", "o": ["Vì em bị ốm", "Vì em mặc quá nhiều áo, thấy nóng", "Vì em rất lạnh", "Vì mẹ gọi em về"], "a": 1}]}, {"u": 14, "t": "宾馆在哪儿？", "tv": "Khách sạn ở đâu?", "s": [["玛丽第一次来北京旅游。", "Mary lần đầu tiên đến Bắc Kinh du lịch."], ["虽然她学过一年汉语，但是她说得还不太好。", "Tuy cô đã học tiếng Trung một năm, nhưng nói vẫn chưa giỏi lắm."], ["下午，天很晴，她从宾馆出来，一个人去玩儿了。", "Buổi chiều trời nắng đẹp, cô ra khỏi khách sạn, đi chơi một mình."], ["她看了很多有意思的东西，玩儿得非常高兴。", "Cô xem rất nhiều thứ thú vị, chơi rất vui."], ["晚上，她要回宾馆，但是找不到路了。", "Buổi tối, cô muốn về khách sạn nhưng không tìm được đường."], ["她手里拿着一张纸，上面写着宾馆的名字。", "Cô cầm trong tay một tờ giấy, trên đó có viết tên khách sạn."], ["她问路口的一个孩子：“请问，这个宾馆怎么走？”", "Cô hỏi một đứa trẻ ở ngã tư: “Cho hỏi, đến khách sạn này đi thế nào?”"], ["孩子看了看那张纸，笑着说：“往右走，到路口再往右走。”", "Đứa trẻ nhìn tờ giấy, cười và nói: “Chị rẽ phải, đến ngã tư lại rẽ phải.”"], ["玛丽往右走，再往右走……她往右走了四次。", "Mary rẽ phải, rồi lại rẽ phải… cô rẽ phải tất cả bốn lần."], ["她走回了那个路口，那个孩子还在那儿。", "Cô đi vòng về đúng ngã tư lúc nãy, đứa trẻ vẫn còn ở đó."], ["孩子笑着说：“你看，宾馆就在你后面！”", "Đứa trẻ cười nói: “Chị nhìn kìa, khách sạn ở ngay sau lưng chị!”"], ["玛丽问：“你为什么不早告诉我？”", "Mary hỏi: “Sao em không nói với chị sớm hơn?”"], ["孩子说：“因为你问的是‘怎么走’啊！”", "Đứa trẻ nói: “Vì chị hỏi là ‘đi thế nào’ mà!”"]], "q": [{"q": "Mary đã học tiếng Trung bao lâu?", "o": ["Hai năm", "Nửa năm", "Ba năm", "Một năm"], "a": 3}, {"q": "Mary cầm gì trong tay?", "o": ["Một cây bút chì", "Tờ giấy ghi tên khách sạn", "Một tờ báo", "Điện thoại"], "a": 1}, {"q": "Thực ra khách sạn ở đâu?", "o": ["Ngay sau lưng Mary, ở ngã tư đó", "Cạnh trường đại học", "Rất xa, phải đi xe buýt", "Bên trái ga tàu"], "a": 0}]}, {"u": 15, "t": "新年的火车票", "tv": "Vé tàu dịp năm mới", "s": [["新年快要到了，大家都想回家。", "Năm mới sắp đến rồi, ai cũng muốn về nhà."], ["李月在北京工作，她的家离北京很远。", "Lý Nguyệt làm việc ở Bắc Kinh, nhà cô cách Bắc Kinh rất xa."], ["她已经一年没回家了，她很想妈妈和妹妹。", "Cô đã một năm chưa về nhà, rất nhớ mẹ và em gái."], ["她在手机上买火车票，但是票都没有了。", "Cô mua vé tàu trên điện thoại, nhưng vé đã hết sạch."], ["十二月三十日，她很早就去了火车站。", "Ngày ba mươi tháng mười hai, cô ra ga tàu từ rất sớm."], ["那天是阴天，火车站里的人非常多。", "Hôm đó trời âm u, trong ga tàu rất đông người."], ["她等了五个小时，都下午四点了，还是没有票。", "Cô đợi năm tiếng, đã bốn giờ chiều rồi mà vẫn không có vé."], ["李月很不高兴，她给妹妹打电话：“对不起，今年我不能回家了。”", "Lý Nguyệt rất buồn, cô gọi điện cho em gái: “Xin lỗi, năm nay chị không về nhà được rồi.”"], ["妹妹笑着说：“姐姐，你往后面看看。”", "Em gái cười nói: “Chị ơi, chị nhìn ra phía sau xem.”"], ["李月往后面一看，妈妈和妹妹手里拿着很多东西，就站在她后面！", "Lý Nguyệt quay ra sau nhìn, mẹ và em gái đang xách rất nhiều đồ, đứng ngay sau lưng cô!"], ["妹妹说：“你买不到票，我们就坐火车来北京了！”", "Em gái nói: “Chị không mua được vé thì bọn em đi tàu lên Bắc Kinh luôn!”"], ["这是李月过得最快乐的一个新年。", "Đó là cái Tết vui nhất mà Lý Nguyệt từng đón."]], "q": [{"q": "Vì sao Lý Nguyệt không mua được vé trên điện thoại?", "o": ["Điện thoại bị hỏng", "Vé quá đắt", "Vé đã hết", "Cô không biết cách mua"], "a": 2}, {"q": "Lý Nguyệt đã đợi ở ga tàu bao lâu?", "o": ["Năm tiếng", "Hai tiếng", "Bốn tiếng", "Cả ngày"], "a": 0}, {"q": "Cuối truyện, ai đứng sau lưng Lý Nguyệt?", "o": ["Một người bạn", "Nhân viên nhà ga", "Bố và anh trai", "Mẹ và em gái"], "a": 3}]}];

